        m_is_paired = mfe[i] != '.'
        if t_is_paired != m_is_paired:
            mism.append(i)
    if not mism:
        # mutate random
        for _ in range(2):
            i=random.randrange(n); s[i]=random.choice('ACGU')
    else:
        for i in random.sample(mism, min(3,len(mism))):
            s[i] = random.choice('ACGU')
    return ''.join(s)

